        let my_position = e.vcall(a, ACTOR_SLOT_POSITION, &args![]).u32();
        let out = e
            .call(POINT_DIFFERENCE, &args![my_position, difference, position])
            .u32();
        e.call(POINT_LENGTH, &args![out]).f32()
